$header = Get-Content (Join-Path $root 'Source/PixelArena/ArenaGameMode.h') -Raw
$config = Get-Content (Join-Path $root 'Config/DefaultGame.ini') -Raw
$failed = $false
if ($header -notmatch 'UPROPERTY\s*\(\s*\)\s*TObjectPtr<UArenaScoreTracker>\s+ScoreTracker\b') {
    Write-Output 'FAIL: ScoreTracker must be a reflected TObjectPtr to survive garbage collection.'
    $failed = $true
}
$packaging = [regex]::Match($config, '(?ms)^\[/Script/UnrealEd.ProjectPackagingSettings\]\s*(.*?)(?=^\[|\z)').Groups[1].Value
if ($packaging -notmatch '(?m)^\+DirectoriesToAlwaysCook=\(Path="/Game/Data/Palettes"\)\s*$') {
    Write-Output 'FAIL: Packaging must explicitly cook /Game/Data/Palettes for the runtime string load.'
    $failed = $true
}
if ($failed) { exit 1 }
Write-Output 'PASS: ScoreTracker is retained through a reflected TObjectPtr.'
Write-Output 'PASS: Packaging explicitly cooks /Game/Data/Palettes.'

